{
 "research_concepts": ["player absence", "offensive reorganization", "pre-absence initiation profile", "teammate usage redistribution", "primary play types", "closest-profile teammate gain", "absorption vs cascade after absence"],
 "methodological_questions": [
  "Can a teammate's similarity to the absent player's pre-absence initiation profile (or minutes / same-position minutes) predict who gains most in the absent player's primary play types?",
  "Is 11 cases (148 spells, non-independent within case) enough power for a test of the closest-profile gainer claim?",
  "Can profile similarity be measured without using post-absence outcomes (outcome leakage)?",
  "Do injury type, role change, and regression to the mean confound attribution of post-absence gains?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "Closest prior study of this concept (play-type replacement similarity vs absorb/cascade). Mean similarity was +0.863 for ABSORBED vs +0.848 for CASCADE, and Spearman(sim, -gap) = -0.19, recorded as wrong-signed. Similarity did not separate absorption from cascade and was almost always findable. Recorded failure mechanism: B_powered_null. Sample and power were NOT_RECORDED; validation was no_validation_recorded."
  },
  {
   "id": "FAM:SF-APPS-088",
   "status_as_recorded": "supported",
   "finding": "Connector absence displaced team offensive identity (D_A) more than usage-matched non-organizer absence (paired dD_A +0.1151, P(conn>ctrl)=81.2%, n=96 matched pairs; n=25 vs terminal). Excludes organizers from the licensed comparison. Relevant to absence-driven reorganization, but it tests team identity, not the closest-profile teammate gain."
  },
  {
   "id": "FAM:SF-APPS-025",
   "status_as_recorded": "untestable",
   "finding": "Post-hoc matched-pair test of adapt vs continue after a suppressed play type. Group B (n=255 pairs, 242 games at caliper 0.10) was a reconstructed post-hoc cohort, and its CI included 0 (p=0.386). Recorded failure mechanism: A_unanswerable."
  },
  {
   "id": "FAM:SF-APPA-063",
   "status_as_recorded": "supported",
   "finding": "Holdout play-type ranking from training data correlated with held-out efficiency (median rho +0.539; 10.5% of rows had rho<0). Doc caveat: top-3 lift partly reflects league-wide high-efficiency play types. Relevant only as a caution about play-type labels and league-wide effects."
  },
  {
   "id": "FAM:SF-APPS-036",
   "status_as_recorded": "supported",
   "finding": "Player-level BEST vs AVOID PPP gap of +0.427 in the same direction as the team gap, but only 3 players cleared n>=30 in both tiers. Relevant as a caution about per-player sample size."
  },
  {
   "id": "FAM:SF-APPA-048",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Exploratory player-level BEST vs AVOID H2 gaps across 78 players with min 5 rows per tier. Results were mixed in sign and n was small for most players. Relevant as a caution about per-player gaps on single-game data."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-052",
   "what_failed": "Using play-type/initiation similarity to separate absorbed from cascaded play-type volume after a player's absence.",
   "why": "Recorded as B_powered_null with the similarity signal wrong-signed (Spearman -0.19). Recorded limit: LIM:label_or_classification_error (RISK:LABEL_ERROR). Power was not recorded, so the null cannot be assumed to be well-powered."
  },
  {
   "id": "FAM:SF-APPA-048",
   "what_failed": "Per-player gap estimation from small single-game play-type samples.",
   "why": "Recorded as A_unanswerable with RISK:PLACEBO_DEPENDENCE; n was small for most players, and no multiplicity or clustered test was run."
  },
  {
   "id": "FAM:SF-APPS-025",
   "what_failed": "Post-hoc comparison of successful vs unsuccessful adaptation cohorts.",
   "why": "Recorded as A_unanswerable: the Group B cohort was reconstructed post hoc, not validated, and the caliper-0.10 CI included 0."
  }
 ],
 "evidence_establishes": [
  "Similarity-based replacement identification did not separate absorption from cascade in the closest prior study (SF-CHT-052), and its direction was wrong-signed.",
  "Per-player and post-hoc cohort analyses in this project have repeatedly been underpowered or unanswerable at the player level (SF-APPA-048, SF-APPS-025, SF-APPS-036).",
  "Absence-related team identity effects have been detected with large matched samples (SF-APPS-088, n=96 pairs), so absence analysis is feasible when the sample is much larger than 11 cases."
 ],
 "evidence_does_not_establish": [
  "No retrieved record tests the specific claim that the closest pre-absence-profile teammate is the largest gainer in the absent player's primary play types.",
  "No retrieved record reports the power or sample size of SF-CHT-052, so its null cannot be taken as a powered negative result for this question.",
  "Nothing retrieved shows how many of the 11 cases have usable pre-absence and post-absence initiation data, or how injury type and role change affect them."
 ],
 "own_inferences": [
  "With 11 cases, even a true effect would be hard to distinguish from noise. The 148 spells are repeated observations within those cases, not 148 independent units.",
  "The closest-profile definition depends on a choice of similarity metric (initiation share, total minutes, or same-position minutes), and each choice may produce a different gainer. Choosing the metric after seeing outcomes would be a forking-paths problem.",
  "Defining 'primary types' from the absent player's own pre-absence usage and then measuring gains on the same play-type possessions may build the outcome into the label.",
  "Regression to the mean is likely: the teammate with the largest post-absence gain may simply be the one whose baseline was lowest."
 ],
 "uncertainties": [
  "Power and sample details for SF-CHT-052 were NOT_RECORDED.",
  "Whether the 2025-26 regular season data (complete from 2026-04-13) and the partial 2025-26 playoffs (complete from 2026-06-21) are used matters for the 11-case count. This could change if partial playoff files are included.",
  "The retrieved set has no record of play-type classification reliability for the play-by-play derived types.",
  "No prior record defines how absence cases were selected (injury vs rest vs trade), so the 11-case set may be selected on post-absence outcomes."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The closest prior study (SF-CHT-052) found that similarity did not separate absorption from cascade and was wrong-signed. That lowers the prior that profile similarity will predict the largest gainer. Combined with the 11-case sample and the player-level underpowering in SF-APPA-048 and SF-APPS-025, the evidence points toward not running the question as posed."
 },
 "testability": {
  "p_testable": 0.15,
  "blocking_constraints": [
   {"code": "SAMPLE_SIZE_POWER", "text": "11 absence cases give too few independent units for a reliable test of who gains most; 148 spells are clustered within cases."},
   {"code": "MEASURE_RELIABILITY", "text": "Initiation-profile similarity and play-type classification may be unreliable, as the SF-CHT-052 label-error caveat suggests."},
   {"code": "OUTCOME_DERIVED_LABEL", "text": "Defining primary types and measuring gains on the same possessions can build the outcome into the label."},
   {"code": "CONFOUNDING", "text": "Injury type, role change, and minute changes after absence can produce gains unrelated to profile similarity."},
   {"code": "RTM_SELECTION", "text": "The largest gainer may be the teammate with the lowest baseline, so the gain could be regression to the mean."}
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF-CHT-052", "FAM:SF-APPS-088", "FAM:SF-APPS-025"],
  "summary": "The closest prior study (SF-CHT-052) tested similarity-based replacement vs absorb/cascade and found no separation, with the wrong-signed effect recorded as B_powered_null but with power NOT_RECORDED. SF-APPS-088 showed that absence effects on team identity are detectable with large matched samples but does not address the closest-profile teammate. No retrieved study directly tests the closest-profile gainer claim, so the question is only partly addressed."
 },
 "risks": [
  {"code": "SAMPLE_SIZE_POWER", "text": "11 cases, with 148 non-independent spells, gives very low power to detect the closest-profile gainer effect."},
  {"code": "LABEL_ERROR", "text": "Play-type and initiator labels derived from play-by-play may misclassify possessions, as recorded for SF-CHT-052."},
  {"code": "MEASURE_RELIABILITY", "text": "Profile similarity depends on the chosen metric (initiation share, minutes, or same-position minutes), and results may vary across metrics."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "Primary play types defined from the same post-absence data used to measure gains would make the test circular."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "Using post-absence information to choose the closest-profile teammate would leak outcome information into the predictor."},
  {"code": "RTM_SELECTION", "text": "Gainers chosen by largest post-absence change are likely to be selected partly by noise and regression to the mean."},
  {"code": "CONFOUNDING", "text": "Injury type, role change, and simultaneous roster moves can drive redistribution independently of profile similarity."},
  {"code": "MULTIPLE_TESTING", "text": "Several similarity metrics and play-type definitions would multiply the chance of a spurious significant result."},
  {"code": "PLACEBO_DEPENDENCE", "text": "Per-player gap analyses in prior work (SF-APPA-048) were small-n and not clustered, and placebo checks are not specified here."}
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.2,
  "untestable": 0.35,
  "artifact": 0.05,
  "uncertain": 0.35
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Minimum viable: descriptive per-case pattern of which teammate gains most in the absent player's primary play types, and whether the closest-profile teammate is among them. No causal or confirmatory claim.",
  "unit": "Absence case (player-absence event), with spells as nested observations.",
  "sample": "The 11 cases as recorded, using only cases with pre-absence and post-absence play-by-play available from the 2022-23 to 2025-26 seasons. Exclude partial 2025-26 playoff files before 2026-06-21.",
  "power": "Not powered for inference at n=11. Report descriptively with per-case intervals only. Any confirmatory test would need a substantially larger set of absence events, not available here.",
  "controls": "Pre-register the similarity metric (initiation share, primary) and the primary-type definition from pre-absence data only. Adjust for injury type, minutes change, and roster changes. Use a regression-to-the-mean baseline (e.g., the teammate's pre-absence rate vs a matched non-absence window).",
  "falsification": "The claim fails if the closest-profile teammate is not the largest gainer in most cases and the wrong-signed pattern from SF-CHT-052 persists in the descriptive comparison.",
  "multiplicity": "Single pre-registered primary metric and play-type definition. Alternate metrics (minutes, same-position minutes) reported as secondary descriptive results with a correction stated in advance.",
  "decision_rule": "Proceed to any inferential claim only if the event count rises well above 11 and similarity beats a minutes-matched and a random-teammate baseline on held-out cases; otherwise report as descriptive and not supportive.",
  "data_version": "NBA 2022-23 to 2025-26 regular season and playoffs; 2025-26 regular season complete from 2026-04-13; 2025-26 playoffs complete from 2026-06-21 (exclude earlier partial files)."
 }
}

